INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q0','nism-10a-z0','Under SEBI (Investment Advisers) Regulations, what is the maximum advisory fee that can be charged under the AUM-based fee model per client family per annum?','["1.5% of AUM","2.0% of AUM","2.5% of AUM","5.0% of AUM"]',2,'Under SEBI RIA regulations, the maximum annual fee for the AUM-based model is 2.5% of AUM per family, or ₹1,25,000 under the fixed fee model.',0) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q1','nism-10a-z0','What is the standard recommended emergency fund size for a salaried individual with stable employment?','["1 month of discretionary expenses","3 to 6 months of mandatory household fixed expenses","2 years of total salary","10% of equity portfolio"]',1,'Financial planning standards dictate an emergency liquidity buffer of 3 to 6 months of mandatory household fixed expenses (rent, EMIs, utilities, groceries) in liquid instruments.',1) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q2','nism-10a-z0','Under Capital Asset Pricing Model (CAPM), what does Beta (β) measure?','["The company-specific unsystematic risk","The sensitivity of an asset’s returns relative to the overall market portfolio (systematic risk)","The dividend payout ratio","The total debt-to-equity ratio"]',1,'Beta measures systematic risk: the sensitivity of a stock or portfolio''s returns relative to movements in the broad market index.',2) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q3','nism-10a-z0','Which ratio measures an individual''s total debt servicing obligations as a percentage of their net monthly take-home income?','["Solvency Ratio","Debt-to-Income / Debt Servicing Ratio","Liquidity Ratio","Savings Ratio"]',1,'The Debt-to-Income (DTI) or Debt Servicing Ratio divides total monthly debt payments by gross/net monthly income; ideally it should not exceed 40-45%.',3) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q4','nism-10a-z0','Can a SEBI Registered Investment Adviser (RIA) receive distribution commissions from mutual fund AMCs for products recommended to their advisory clients?','["Yes, up to 1% trail commission is allowed","No, SEBI RIA regulations strictly prohibit receiving commissions or fees from product manufacturers for advisory clients","Yes, provided it is disclosed in writing","Only for direct equity stocks"]',1,'SEBI strictly mandates client-level segregation: An RIA cannot receive any distribution commission or fee from AMCs/issuers for products recommended to an advisory client.',4) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
