INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z1-q6','nism-10a-z1','By the Rule of 72, money earning 24% p.a. doubles in about:','["4.2 years","3.3 years","6.0 years","3.0 years"]',3,'Years to double ≈ 72 ÷ rate.',6) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z1-q7','nism-10a-z1','Monthly expenses are ₹45,000 today. With inflation of 4% p.a., the monthly expense after 20 years will be approximately:','["₹98,601","₹90,000","₹81,000","₹91,162"]',0,'Future expense = today''s expense × (1 + inflation)^n.',7) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
